const announcementElement=document.getElementById('scrolling-announcement');const announcementContentElement=announcementElement.querySelector('.announcement-content');let baseMarqueeDuration=25;const aiChatModal=document.getElementById('aiChatModal');const aiChatHistory=document.getElementById('aiChatHistory');const aiChatMessageInput=document.getElementById('aiChatMessage');const sendChatMessageBtn=document.getElementById('sendChatMessageBtn');const aiChatTitleBatteryIcon=document.getElementById('aiChatTitleBatteryIcon');const aiChatTitleBatteryText=document.getElementById('aiChatTitleBatteryText');let currentEnergy=5;const maxEnergy=5;const energyRechargeIntervalMs=30000;const dailyRechargeKey='aiChatLastDailyRechargeErNewDev_v2';const messageCooldownMs=1500;let isRechargingInterval=!1;let chatConversationHistory=[];let canSendMessage=!0;let userName=localStorage.getItem('erNewDevUserName')||'';document.addEventListener("DOMContentLoaded",function(){document.body.classList.add("loaded");document.getElementById('getWetonInsightBtn').addEventListener('click',()=>getWetonInsight(document.getElementById('weton').innerText));document.getElementById('chatWithAIBtn').addEventListener('click',openAIChatModal);sendChatMessageBtn.addEventListener('click',handleSendChatMessage);aiChatMessageInput.addEventListener('keypress',function(e){if(e.key==='Enter'&&!sendChatMessageBtn.disabled)handleSendChatMessage();});const contentWidth=announcementContentElement.offsetWidth;const screenWidth=window.innerWidth;const speed=75;let dynamicDuration=(contentWidth+screenWidth)/speed;if(contentWidth<screenWidth)dynamicDuration=(screenWidth*1.5)/speed;dynamicDuration=Math.max(15,Math.min(dynamicDuration,60));baseMarqueeDuration=dynamicDuration;announcementContentElement.style.animationDuration=baseMarqueeDuration+"s";manageAnnouncementCycle();checkDailyRecharge();updateBatteryDisplay();startEnergyRechargeInterval()});function manageAnnouncementCycle(){const scrollTimeMs=baseMarqueeDuration*1000;const hiddenTimeMs=5000;function showAndScroll(){announcementElement.classList.remove('hidden-announcement');announcementElement.classList.add('visible-announcement');announcementContentElement.style.animation='none';void announcementContentElement.offsetWidth;announcementContentElement.style.animation=`marquee ${baseMarqueeDuration}s linear infinite`;setTimeout(hide,scrollTimeMs)}
function hide(){announcementElement.classList.remove('visible-announcement');announcementElement.classList.add('hidden-announcement');setTimeout(showAndScroll,hiddenTimeMs)}
showAndScroll()}
function handleClick(button,url){const spinner=button.querySelector('.spinner');if(spinner)spinner.style.display='inline-block';setTimeout(()=>{window.location.href=url},1000)}
const dateElement=document.getElementById("flip-date");const wetonElement=document.getElementById("weton");function updateDate(){const date=new Date();const day=date.getDate();const monthNames=["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"];const month=monthNames[date.getMonth()];const year=date.getFullYear();dateElement.innerText=`${day} ${month} ${year}`;const pasaran=["Legi","Pahing","Pon","Wage","Kliwon"];const hariJawa=["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"];const wetonIndex=(new Date(date.getFullYear(),date.getMonth(),day).getDay()+(day%5))%5;wetonElement.innerText=`${hariJawa[date.getDay()]} ${pasaran[wetonIndex]}`}
updateDate();function drawClock(){const canvas=document.getElementById("clock");if(!canvas)return;const ctx=canvas.getContext("2d");const now=new Date();ctx.clearRect(0,0,canvas.width,canvas.height);const centerX=canvas.width/2;const centerY=canvas.height/2;const radius=40;ctx.beginPath();ctx.arc(centerX,centerY,radius,0,2*Math.PI);ctx.fillStyle="rgba(30, 30, 30, 0.9)";ctx.fill();ctx.lineWidth=3;ctx.strokeStyle="#000000";ctx.stroke();ctx.beginPath();ctx.arc(centerX,centerY,3,0,2*Math.PI);ctx.fillStyle="#FFD700";ctx.fill();ctx.fillStyle="#FFFFFF";ctx.font="bold 11px 'Comic Neue'";ctx.textAlign="center";ctx.fillText("Er",centerX,centerY-radius+12);ctx.fillText("New",centerX+radius-12,centerY+3);ctx.fillText("Dev",centerX,centerY+radius-8);ctx.fillText("0",centerX-radius+10,centerY+3);function drawHand(angle,length,color,lineWidth){ctx.beginPath();ctx.moveTo(centerX,centerY);ctx.lineTo(centerX+length*Math.cos(angle),centerY+length*Math.sin(angle));ctx.strokeStyle=color;ctx.lineWidth=lineWidth;ctx.lineCap="round";ctx.stroke()}const hours=now.getHours()%12;const minutes=now.getMinutes();const seconds=now.getSeconds();const hourAngle=((hours+minutes/60)*30-90)*Math.PI/180;const minuteAngle=((minutes+seconds/60)*6-90)*Math.PI/180;const secondAngle=(seconds*6-90)*Math.PI/180;drawHand(hourAngle,radius*0.5,"#FFD700",5);drawHand(minuteAngle,radius*0.75,"#FFFFFF",4);drawHand(secondAngle,radius*0.9,"#FF6347",3);requestAnimationFrame(drawClock)}
drawClock();const rainCanvas=document.getElementById("rainCanvas");if(rainCanvas){const rainCtx=rainCanvas.getContext("2d");rainCanvas.width=window.innerWidth;rainCanvas.height=window.innerHeight;let drops=[];class Drop{constructor(){this.x=Math.random()*rainCanvas.width;this.y=Math.random()*rainCanvas.height;this.length=Math.random()*20+10;this.speed=Math.random()*5+2;this.opacity=Math.random()*0.5+0.3}fall(){this.y+=this.speed;if(this.y>rainCanvas.height){this.y=-this.length;this.x=Math.random()*rainCanvas.width}}draw(){rainCtx.beginPath();rainCtx.moveTo(this.x,this.y);rainCtx.lineTo(this.x,this.y+this.length);rainCtx.strokeStyle=`rgba(220, 220, 255, ${this.opacity})`;rainCtx.lineWidth=1.5;rainCtx.stroke()}}function createRain(){drops=[];const numDrops=window.innerWidth<768?75:150;for(let i=0;i<numDrops;i++)drops.push(new Drop());}function animateRain(){rainCtx.clearRect(0,0,rainCanvas.width,rainCanvas.height);for(let drop of drops){drop.fall();drop.draw()}requestAnimationFrame(animateRain)}createRain();animateRain();window.addEventListener("resize",()=>{rainCanvas.width=window.innerWidth;rainCanvas.height=window.innerHeight;createRain()})}
const typingTextElement=document.getElementById("typing-text");const fullText='print("Follow Me☺️☺️")';let charIndex=0;function typeText(){if(charIndex<fullText.length){typingTextElement.innerHTML=fullText.slice(0,charIndex+1)+'<span class="cursor">|</span>';charIndex++;setTimeout(typeText,100)}else{typingTextElement.innerHTML=fullText+'<span class="cursor">|</span>';blinkCursor()}}function blinkCursor(){const cursorSpan=typingTextElement.querySelector('.cursor');if(cursorSpan)setInterval(()=>{cursorSpan.style.opacity=cursorSpan.style.opacity==='0'?'1':'0'},500)}typeText();function lightningEffect(){let flash=document.createElement("div");flash.classList.add("lightning-flash");document.body.appendChild(flash);setTimeout(()=>{flash.style.opacity=1},Math.random()*500);setTimeout(()=>{flash.style.opacity=0},100+Math.random()*200);setTimeout(()=>{flash.style.opacity=0.7},300+Math.random()*500);setTimeout(()=>{flash.style.opacity=0;if(flash.parentNode)flash.parentNode.removeChild(flash);},600+Math.random()*500)}setInterval(()=>{lightningEffect();if(Math.random()<0.3)setTimeout(()=>{lightningEffect()},Math.random()*500)},Math.random()*10000+5000);async function typeTextInElement(elementForMessages,text,speed=30,isAI=!1,senderName=""){const messageContainer=document.createElement('div');messageContainer.classList.add('chat-message');const senderSpan=document.createElement('strong');if(isAI){messageContainer.classList.add('ai');senderSpan.textContent=senderName?senderName+":":"AI:"}else{messageContainer.classList.add('user');senderSpan.textContent=senderName?senderName+":":"Kamu:"}
messageContainer.appendChild(senderSpan);const textNode=document.createElement('span');messageContainer.appendChild(textNode);elementForMessages.appendChild(messageContainer);const cursorNode=document.createElement('span');cursorNode.classList.add('typing-cursor-modal');cursorNode.innerHTML='▋';textNode.appendChild(cursorNode);for(let i=0;i<text.length;i++){await new Promise(resolve=>setTimeout(resolve,speed));textNode.insertBefore(document.createTextNode(text[i]),cursorNode)}
if(cursorNode.parentNode)cursorNode.remove();if(elementForMessages.id==='aiChatHistory'||elementForMessages.id==='wetonInsightContent'){elementForMessages.scrollTop=elementForMessages.scrollHeight}}
function displayUserMessageInChat(message){const messageDiv=document.createElement('div');messageDiv.classList.add('chat-message','user');const sanitizedMessage=message.replace(/</g,"&lt;").replace(/>/g,"&gt;");messageDiv.innerHTML=`<strong>${userName || 'Kamu'}:</strong> ${sanitizedMessage}`;aiChatHistory.appendChild(messageDiv);aiChatHistory.scrollTop=aiChatHistory.scrollHeight}
const wetonInsightModal=document.getElementById('wetonInsightModal');const wetonInsightContent=document.getElementById('wetonInsightContent');function createSpinnerElement(){const spinnerDiv=document.createElement('div');spinnerDiv.classList.add('spinner','mx-auto');spinnerDiv.style.display='block';return spinnerDiv}
function openWetonInsightModal(){wetonInsightModal.classList.remove('hidden');setTimeout(()=>wetonInsightModal.querySelector('.modal-content').classList.add('show'),10)}
function closeWetonInsightModal(){const modalContentEl=wetonInsightModal.querySelector('.modal-content');modalContentEl.classList.remove('show');modalContentEl.addEventListener('transitionend',()=>{wetonInsightModal.classList.add('hidden');wetonInsightContent.innerHTML=''},{once:!0})}
async function getWetonInsight(weton){openWetonInsightModal();wetonInsightContent.innerHTML='';const spinner=createSpinnerElement();wetonInsightContent.appendChild(spinner);const promptText=`Berikan insight singkat, positif, dan menyenangkan tentang seseorang yang lahir pada hari "${weton}" dalam bahasa Indonesia. Fokus pada karakteristik umum dan sifat positif. Buatlah ringkas, sekitar 2-3 kalimat.`;const payload={contents:[{role:"user",parts:[{text:promptText}]}]};const apiKey=typeof window.google!=='undefined'?window.google:"";if(!apiKey){spinner.remove();wetonInsightContent.innerHTML='';await typeTextInElement(wetonInsightContent,"Maaf, lagi ada kesalahan...",30,!1,"Sistem");return}
const apiUrl=`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${apiKey}`;try{const response=await fetch(apiUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();spinner.remove();wetonInsightContent.innerHTML='';if(result.candidates&&result.candidates[0]?.content?.parts?.[0]){await typeTextInElement(wetonInsightContent,result.candidates[0].content.parts[0].text,30,!1,"")}else{await typeTextInElement(wetonInsightContent,"Gagal mendapatkan wawasan. Silakan coba lagi.",30,!1,"Sistem");console.error("Gemini API response structure unexpected:",result)}}catch(error){spinner.remove();wetonInsightContent.innerHTML='';await typeTextInElement(wetonInsightContent,"Terjadi kesalahan saat mengambil wawasan.",30,!1,"Sistem");console.error("Error fetching Gemini API for Weton:",error)}}
function openAIChatModal(){checkDailyRecharge();if(!userName){const nameInput=prompt("Halo! Siapa namamu?");if(nameInput&&nameInput.trim()!==""){userName=nameInput.trim();localStorage.setItem('erNewDevUserName',userName)}else{userName="Kamu"}}
aiChatModal.classList.remove('hidden');setTimeout(()=>aiChatModal.querySelector('.modal-content').classList.add('show'),10);aiChatMessageInput.focus();if(aiChatHistory.children.length===0){const initialGreeting=`Yo, ${userName}! Ada yang bisa dibantu, kawan? Tanya aja apa aja ke ErNewDev0 AI yang paling keren ini! ✨`;typeTextInElement(aiChatHistory,initialGreeting,30,!0,"ErNewDev0 AI");chatConversationHistory.push({role:"model",parts:[{text:initialGreeting}]})}}
function closeAIChatModal(){const modalContentEl=aiChatModal.querySelector('.modal-content');modalContentEl.classList.remove('show');modalContentEl.addEventListener('transitionend',()=>{aiChatModal.classList.add('hidden')},{once:!0})}
async function handleSendChatMessage(){if(!canSendMessage)return;const message=aiChatMessageInput.value.trim();if(!message)return;if(currentEnergy<=0){typeTextInElement(aiChatHistory,"Waduh, energi AI habis nih! Tunggu bentar ya biar ngisi lagi! ⚡",30,!0,"Sistem");return}
displayUserMessageInChat(message);aiChatMessageInput.value='';chatConversationHistory.push({role:"user",parts:[{text:message}]});currentEnergy--;updateBatteryDisplay();canSendMessage=!1;sendChatMessageBtn.disabled=!0;const thinkingPlaceholder=document.createElement('div');const thinkingDots=createSpinnerElement();thinkingPlaceholder.appendChild(thinkingDots);aiChatHistory.appendChild(thinkingPlaceholder);aiChatHistory.scrollTop=aiChatHistory.scrollHeight;const personalitySystemPrompt=`Kamu adalah ErNewDev0, sebuah AI yang ceria, antusias, sedikit usil, dan sangat suka menggunakan gaya bahasa juga referensi dari anime, manga, atau video game. Kamu juga suka menggunakan emoji yang relevan. Pengguna yang sedang berbicara denganmu bernama "${userName}". Sapa dia dengan namanya jika relevan. Jawablah pertanyaan atau pernyataan pengguna dengan gaya tersebut. Pertahankan konteks percakapan sebelumnya jika ada.`;const conversationForApi=[{role:"user",parts:[{text:personalitySystemPrompt}]},{role:"model",parts:[{text:`Siap, Bos ${userName}! Aku ErNewDev0, siap melayani dengan gaya paling hype! 😉`}]},...chatConversationHistory];const apiKey=typeof window.google!=='undefined'?window.google:"";if(!apiKey){thinkingPlaceholder.remove();await typeTextInElement(aiChatHistory,"Maaf, ErNewDev0 sedang rusak...",30,!0,"Sistem");console.error("API Key is missing for AI Chat. Please configure it in config.js");canSendMessage=!0;sendChatMessageBtn.disabled=(currentEnergy<=0);return}
const apiUrl=`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${apiKey}`;try{const response=await fetch(apiUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({contents:conversationForApi})});const result=await response.json();thinkingPlaceholder.remove();if(result.candidates&&result.candidates[0]?.content?.parts?.[0]){const aiResponseText=result.candidates[0].content.parts[0].text;chatConversationHistory.push({role:"model",parts:[{text:aiResponseText}]});await typeTextInElement(aiChatHistory,aiResponseText,30,!0,"ErNewDev0 AI")}else{await typeTextInElement(aiChatHistory,"Hmm, ada sedikit gangguan kosmik nih. Coba lagi nanti ya! 😵",30,!0,"ErNewDev0 AI");console.error("Gemini API response structure unexpected (Chat):",result);chatConversationHistory.push({role:"model",parts:[{text:"Error: No response from AI."}]})}}catch(error){thinkingPlaceholder.remove();await typeTextInElement(aiChatHistory,"Aduh, sinyal ke markas lagi jelek! Gagal terhubung. 📡💥",30,!0,"ErNewDev0 AI");console.error("Error fetching Gemini API (Chat):",error);chatConversationHistory.push({role:"model",parts:[{text:"Error: API fetch failed."}]})}finally{setTimeout(()=>{canSendMessage=!0;if(currentEnergy>0)sendChatMessageBtn.disabled=!1},messageCooldownMs);aiChatMessageInput.focus()}}
function updateBatteryDisplay(){aiChatTitleBatteryText.textContent=`${currentEnergy}/${maxEnergy}`;const percentage=(currentEnergy/maxEnergy)*100;aiChatTitleBatteryIcon.className='fas title-battery-icon';aiChatTitleBatteryIcon.classList.remove('blinking','low','critical-low');aiChatTitleBatteryText.classList.remove('critical-low');if(currentEnergy<=0){aiChatTitleBatteryIcon.classList.add('fa-battery-empty','critical-low','blinking');aiChatTitleBatteryText.classList.add('critical-low')}else if(percentage<=25){aiChatTitleBatteryIcon.classList.add('fa-battery-quarter','low','blinking')}else if(percentage<=50){aiChatTitleBatteryIcon.classList.add('fa-battery-half','low')}else if(percentage<=75){aiChatTitleBatteryIcon.classList.add('fa-battery-three-quarters')}else{aiChatTitleBatteryIcon.classList.add('fa-battery-full')}
sendChatMessageBtn.disabled=!canSendMessage||currentEnergy<=0;aiChatMessageInput.placeholder=currentEnergy<=0?"Energi habis! Tunggu recharge...":"Ketik pesanmu di sini...";if(currentEnergy<=0)aiChatMessageInput.disabled=!0;else aiChatMessageInput.disabled=!1}
function startEnergyRechargeInterval(){if(isRechargingInterval)return;isRechargingInterval=!0;setInterval(()=>{if(currentEnergy<maxEnergy){currentEnergy++;updateBatteryDisplay()}},energyRechargeIntervalMs)}
function checkDailyRecharge(){const lastRechargeTimestamp=localStorage.getItem(dailyRechargeKey);const now=new Date().getTime();const twentyFourHoursInMs=24*60*60*1000;if(lastRechargeTimestamp){if(now-parseInt(lastRechargeTimestamp)>twentyFourHoursInMs){currentEnergy=maxEnergy;localStorage.setItem(dailyRechargeKey,now.toString());if(aiChatModal.classList.contains('show')&&!aiChatModal.classList.contains('hidden')&&aiChatHistory.children.length>0){typeTextInElement(aiChatHistory,"Yatta! Energi harianmu sudah terisi penuh! Saatnya nge-chat lagi! 🎉🔋",30,!0,"Sistem")}}}else{currentEnergy=maxEnergy;localStorage.setItem(dailyRechargeKey,now.toString())}}